struct kioctx *ioctx_alloc(unsigned nr_events)
{
    struct kioctx *ctx;
    int err;

    if (nr_events >= (UINT_MAX / sizeof(struct io_event)))
        return ERR_PTR(-EINVAL);

    /* Adjust the number of events based on CPU distribution */
    nr_events = max_t(unsigned, nr_events, 1);

    ctx = kzalloc(sizeof(*ctx), GFP_KERNEL);
    if (!ctx)
        return ERR_PTR(-ENOMEM);

    spin_lock_init(&ctx->ctx_lock);
    init_waitqueue_head(&ctx->wait);

    err = 0;
    if (atomic_inc_return(&nr_async_ios) > max_async_ios) {
        err = -ENOMEM;
        atomic_dec(&nr_async_ios);
    }

    if (err) {
        kfree(ctx);
        return ERR_PTR(err);
    }

    ctx->nr_events = nr_events;
    ctx->events = kmalloc_array(nr_events, sizeof(struct io_event), GFP_KERNEL);
    if (!ctx->events) {
        err = -ENOMEM;
        atomic_dec(&nr_async_ios);
