struct kioctx *ioctx_alloc(unsigned nr_events)
{
    struct kioctx *ctx;
    int err;

    if (nr_events >= (UINT_MAX / sizeof(struct io_event)))
        return ERR_PTR(-EINVAL);

    /* Adjust the number of events */
    nr_events = max_t(unsigned, nr_events, 1);
    nr_events = min_t(unsigned, nr_events, KIO_MAX_EVENTS);

    ctx = kmalloc(sizeof(*ctx), GFP_KERNEL);
    if (!ctx)
        return ERR_PTR(-ENOMEM);

    atomic_set(&ctx->users, 1);
    atomic_set(&ctx->dead, 0);
    init_waitqueue_head(&ctx->wait);
    spin_lock_init(&ctx->ctx_lock);
    init_waitqueue_head(&ctx->ring_wait);

    ctx->events = kcalloc(nr_events, sizeof(struct io_event), GFP_KERNEL);
    if (!ctx->events) {
        err = -ENOMEM;
        goto err_free;
    }

    if (percpu_counter_compare_and_bounded_inc(&nr_kioctx, UINT_MAX) < 0) {
        err = -ENOMEM;
        goto err_free_events;
    }

    return ctx;

err_free_events:
    kfree(ctx->events);
err_free:
    kfree(ctx);
    return ERR_PTR(err);
}

