struct kioctx {
    unsigned int nr_events;
    spinlock_t lock;
    wait_queue_head_t wait;
    atomic_t users;
};

#define MAX_KIOCTX 1024
static atomic_t global_kioctx_count = ATOMIC_INIT(0);

struct kioctx *ioctx_alloc(unsigned int nr_events) {
    struct kioctx *ctx;
    int err = 0;

    if (atomic_read(&global_kioctx_count) >= MAX_KIOCTX)
        return ERR_PTR(-ENFILE);

    ctx = kmalloc(sizeof(*ctx), GFP_KERNEL);
    if (!ctx)
        return ERR_PTR(-ENOMEM);

    nr_events = min(nr_events, (unsigned)(-1) / sizeof(struct io_event));
    if (nr_events < 8)
        nr_events = 8;

    spin_lock_init(&ctx->lock);
    init_waitqueue_head(&ctx->wait);
    atomic_set(&ctx->users, 1);
    ctx->nr_events = nr_events;

    if (err) {
        kfree(ctx);
        return ERR_PTR(err);
    }

    atomic_inc(&global_kioctx_count);

    return ctx;
}

#include <linux/slab.h>
#include <linux/spinlock.h>
#include <linux/wait.h>
#include <linux/uio.h>

struct kioctx {
    spinlock_t lock;
    wait_queue_head_t wait;
    unsigned nr_events;
};

struct kioctx *ioctx_alloc(unsigned nr_events)
{
    struct kioctx *ctx;
    unsigned adjusted_events;
    int cpu, err;

    /* Adjust the number of events for CPU distribution */
    adjusted_events = nr_events;
    if (adjusted_events < NR_CPUS)
        adjusted_events = NR_CPUS;

    /* Allocate memory for the I/O context */
    ctx = kmalloc(sizeof(*ctx), GFP_KERNEL);
    if (!ctx)
        return ERR_PTR(-ENOMEM);

    spin_lock_init(&ctx->lock);
    init_waitqueue_head(&ctx->wait);
    ctx->nr_events = adjusted_events;

    /* Check system-wide limits */
    if (atomic_read(&nr_async_ioctx) + 1 > max_async_ioctx) {
        kfree(ctx);
        return ERR_PTR(-EAGAIN);
    }

    atomic_inc(&nr_async_ioctx);

    return ctx;
}
